import {
  type KeyboardEvent as ReactKeyboardEvent,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import "./reveal-list.css";

export interface RevealListProps {
  /** 一行一条，直接写文字（语料命中行就是这么拼的）。 */
  items: string[];
  className?: string;
  /** 每行那块卡片的类名（边框、底色、字体由调用方定）。 */
  itemClassName?: string;
  /** 上下两道「还有内容」的渐隐。 */
  showGradients?: boolean;
  /** 关掉滚动条（内容不长、又不想要一条槽的时候）。 */
  displayScrollbar?: boolean;
  /** 给了它就是可选项列表：能点、能上下键走。不给就是一张纯列表。 */
  onItemSelect?: (item: string, index: number) => void;
  initialSelectedIndex?: number;
}

/**
 * 一条会自己长出来的列表：行滑进滚动窗口就把自己点亮，滚出去再收回去；
 * 上下两头按滚到哪儿渐隐，示意还有内容。
 *
 * 动的地方全在 CSS（行上是 data-in 一个属性，渐隐是 --fade-top/--fade-bottom
 * 两个变量），JS 只负责判断「这一行进来了没有」和写那两个数。
 *
 * 只有给了 onItemSelect 才当选项列表使：这时键盘能在列表里走（上下键 + 回车），
 * 焦点在列表自己身上 —— 不在 window 上拦 Tab，不然整页都 Tab 不动了。
 */
export function RevealList({
  items,
  className = "",
  itemClassName = "",
  showGradients = true,
  displayScrollbar = true,
  onItemSelect,
  initialSelectedIndex = -1,
}: RevealListProps) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const scrollerRef = useRef<HTMLUListElement | null>(null);
  const rowsRef = useRef<Array<HTMLLIElement | null>>([]);
  const [activeIndex, setActiveIndex] = useState(
    onItemSelect ? initialSelectedIndex : -1,
  );
  const listId = useId().replace(/:/g, "-");
  const selectable = Boolean(onItemSelect);

  /* 两道渐隐跟着滚动位置走：滚到哪儿写哪个数，画还是 CSS 画。 */
  const paintFades = useCallback(() => {
    const scroller = scrollerRef.current;
    const root = rootRef.current;
    if (!scroller || !root) return;
    const { scrollTop, scrollHeight, clientHeight } = scroller;
    const top = Math.min(scrollTop / 50, 1);
    const bottom =
      scrollHeight <= clientHeight
        ? 0
        : Math.min((scrollHeight - scrollTop - clientHeight) / 50, 1);
    root.style.setProperty("--fade-top", top.toFixed(3));
    root.style.setProperty("--fade-bottom", bottom.toFixed(3));
  }, []);

  useEffect(() => {
    paintFades();
  }, [items, paintFades]);

  /* 布局之后还会变（字体换上来、容器被撑动、样式到位得晚），
     光靠内容变化那次重画会停在旧值上 —— 尺寸一变就再画一次。 */
  useEffect(() => {
    if (!showGradients) return;
    const scroller = scrollerRef.current;
    if (!scroller || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(paintFades);
    observer.observe(scroller);
    for (const row of rowsRef.current.slice(0, items.length)) {
      if (row) observer.observe(row);
    }
    return () => observer.disconnect();
  }, [items, showGradients, paintFades]);

  /* 行那个「长出来」的位移在没补完之前会往滚动区域外面多探一截 —— 浏览器算
     溢出是把变换后的盒子一起算的 —— 补间一停这截假溢出就没了，可没有任何
     尺寸变化提醒我们。听一声 transitionend 再画一次，数就跟上了。 */
  useEffect(() => {
    if (!showGradients) return;
    const scroller = scrollerRef.current;
    if (!scroller) return;
    const onTransitionEnd = (event: TransitionEvent) => {
      const target = event.target;
      if (target instanceof HTMLElement && target.closest(".reveal-list__row")) {
        paintFades();
      }
    };
    scroller.addEventListener("transitionend", onTransitionEnd);
    return () => scroller.removeEventListener("transitionend", onTransitionEnd);
  }, [showGradients, paintFades]);

  /* 行进没进窗口，交给观察器说 —— 减少动效时整段跳过，CSS 里行本来就是亮着的。 */
  useEffect(() => {
    const scroller = scrollerRef.current;
    if (!scroller) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          entry.target.toggleAttribute("data-in", entry.isIntersecting);
        }
      },
      // 半行露出来才算「进来了」。
      { root: scroller, threshold: 0.5 },
    );
    // 只挂还在的行：换了一拨内容之后，老行不该继续被观察。
    for (const row of rowsRef.current.slice(0, items.length)) {
      if (row) observer.observe(row);
    }
    return () => observer.disconnect();
  }, [items]);

  const moveTo = (next: number) => {
    if (!items.length) return;
    const clamped = Math.max(0, Math.min(next, items.length - 1));
    setActiveIndex(clamped);
    // 走到看不见的行就把它带进视野（就近滚，不多滚）。
    rowsRef.current[clamped]?.scrollIntoView({ block: "nearest" });
  };

  const handleKeyDown = (event: ReactKeyboardEvent<HTMLUListElement>) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      moveTo(activeIndex + (event.key === "ArrowDown" ? 1 : -1));
      return;
    }
    if (event.key === "Home" || event.key === "End") {
      event.preventDefault();
      moveTo(event.key === "Home" ? 0 : items.length - 1);
      return;
    }
    if (event.key === "Enter" || event.key === " ") {
      const picked = activeIndex >= 0 ? items[activeIndex] : undefined;
      if (picked === undefined) return;
      event.preventDefault();
      onItemSelect?.(picked, activeIndex);
    }
  };

  return (
    <div
      ref={rootRef}
      className={["reveal-list", className].filter(Boolean).join(" ")}
    >
      <ul
        ref={scrollerRef}
        className="reveal-list__scroll"
        data-scrollbar={displayScrollbar ? undefined : "hidden"}
        role={selectable ? "listbox" : undefined}
        tabIndex={selectable ? 0 : undefined}
        aria-activedescendant={
          selectable && activeIndex >= 0
            ? `${listId}-row-${activeIndex}`
            : undefined
        }
        onKeyDown={selectable ? handleKeyDown : undefined}
        onScroll={showGradients ? paintFades : undefined}
      >
        {items.map((item, index) => (
          <li
            key={index}
            id={`${listId}-row-${index}`}
            ref={(node) => {
              rowsRef.current[index] = node;
            }}
            className="reveal-list__row"
            data-index={index}
            role={selectable ? "option" : undefined}
            aria-selected={selectable ? index === activeIndex : undefined}
            onMouseEnter={
              selectable ? () => setActiveIndex(index) : undefined
            }
          >
            <div
              className={[
                "reveal-list__item",
                index === activeIndex ? "is-active" : "",
                itemClassName,
              ]
                .filter(Boolean)
                .join(" ")}
              onClick={
                selectable ? () => onItemSelect?.(item, index) : undefined
              }
            >
              <p className="reveal-list__text">{item}</p>
            </div>
          </li>
        ))}
      </ul>

      {showGradients && (
        <>
          <span
            className="reveal-list__fade reveal-list__fade--top"
            aria-hidden="true"
          />
          <span
            className="reveal-list__fade reveal-list__fade--bottom"
            aria-hidden="true"
          />
        </>
      )}
    </div>
  );
}

export default RevealList;
